body.--blur-background:
color-mix(
      in srgb, var(--interactive-normal) var(--blur-opacity-s), transparent
    )
    linear-gradient(
      var(--interactive-normal),
      color-mix( in srgb, var(--interactive-normal) var(--blur-opacity-s), transparent
      )
    )

body.styled-scrollbars.--blur-background:
color-mix(
      in srgb, var(--interactive-normal) var(--blur-opacity-s), transparent
    )
    linear-gradient(
      var(--interactive-normal),
      color-mix( in srgb, var(--interactive-normal) var(--blur-opacity-s), transparent
      )
    )
